def df_to_html(df, float_fmt='{:.2f}', int_cols=None):
    html = '<table><thead><tr>'
    for c in df.columns:
        html += f'<th>{c}</th>'
    html += '</tr></thead><tbody>'
    for idx, row in df.iterrows():
        html += '<tr>'
        html += f'<td><strong>{idx}</strong></td>' if isinstance(idx, str) else f'<td>{idx}</td>'
        for c in df.columns[1:] if isinstance(idx, str) and len(df.columns) == len(row)+1 else df.columns:
            # handle index-as-first-column logic
            pass
    # Simpler: reset index
    df2 = df.reset_index()
    html = '<table><thead><tr>'
    for c in df2.columns:
        html += f'<th>{c}</th>'
    html += '</tr></thead><tbody>'
    for _, row in df2.iterrows():
        html += '<tr>'
        for c in df2.columns:
            v = row[c]
            if isinstance(v, float):
                if abs(v) < 1 and 'Rate' in c or '%' in c or 'Premium' in c:
                    html += f'<td>{v*100:.1f}%</td>'
                elif 'USD' in c or 'Price' in c or 'Margin' in c or 'Retail' in c or 'Resale' in c:
                    html += f'<td>${v:.2f}</td>'
                elif 'Days' in c:
                    html += f'<td>{v:.1f}</td>'
                else:
                    html += f'<td>{v:.2f}</td>'
            elif isinstance(v, int):
                html += f'<td>{v:,}</td>'
            else:
                html += f'<td>{v}</td>'
        html += '</tr>'
    html += '</tbody></table>'
    return html

